#!/usr/bin/env node
/**
 * Writes src/terms.generated.ts from ../terms/member-terms-v1.md, byte for byte, so the Worker serves the
 * exact text the vault's termsHash was computed from. The output is gitignored and regenerated by every
 * build (`npm run build:site`, which dev/dry/deploy run first), so it cannot drift from the file in terms/.
 * /patron/health still compares the served bytes' keccak256 with the contract's termsHash on every probe.
 */
import { readFileSync, writeFileSync } from "node:fs"
import { createHash } from "node:crypto"
import { fileURLToPath } from "node:url"
import { dirname, resolve } from "node:path"

const here = dirname(fileURLToPath(import.meta.url))
const src = resolve(here, "../../terms/member-terms-v1.md")
const out = resolve(here, "../src/terms.generated.ts")
const bytes = readFileSync(src)
const text = bytes.toString("utf8")
if (Buffer.from(text, "utf8").compare(bytes) !== 0) throw new Error("terms file is not valid UTF-8; the served string would not reproduce its bytes")
const sha = createHash("sha256").update(bytes).digest("hex")
writeFileSync(
  out,
  `// generated by scripts/gen-terms.mjs from terms/member-terms-v1.md; do not edit, do not commit\n` +
    `export const TERMS_FILE = "terms/member-terms-v1.md"\n` +
    `export const TERMS_SHA256 = "${sha}"\n` +
    `export const TERMS_TEXT: string = ${JSON.stringify(text)}\n`,
)
console.log(`[gen-terms] ${bytes.length} bytes, sha256 ${sha} -> src/terms.generated.ts`)
